"use strict";dotclear.ready(()=>{const e=dotclear.getData("dc_editor_noembedmedia");dotclear.ToolBar.prototype.elements.noembedmedia={group:"media",type:"button",title:e.title||"External Media (via noembed.com)",icon:e.icon,icon_dark:e.icon_dark,fn:{},fncall:{},open_url:e.open_url,data:{},popup(){globalThis.the_toolbar=this,this.elements.noembedmedia.data={},window.open(this.elements.noembedmedia.open_url,"dc_popup","alwaysRaised=yes,dependent=yes,toolbar=yes,height=500,width=760,menubar=no,resizable=yes,scrollbars=yes,status=no")},gethtml(){const t=this.data;if(""==t.m_object)return!1;let l='<div class="external-media"';return"left"==t.alignment?l+=` ${e.style.class?"class":"style"}="${e.style.left}"`:"right"==t.alignment?l+=` ${e.style.class?"class":"style"}="${e.style.right}"`:"center"==t.alignment&&(l+=` ${e.style.class?"class":"style"}="${e.style.center}"`),l+=`>\n${t.m_object}`,t.title&&(t.url&&(t.title=`<a href="${t.url}">${t.title}</a>`),l+=`\n<br>${t.title}`),l+="\n</div>",l}},dotclear.ToolBar.prototype.elements.noembedmedia.fn.wiki=function(){this.elements.noembedmedia.popup.call(this)},dotclear.ToolBar.prototype.elements.noembedmedia.fn.xhtml=function(){this.elements.noembedmedia.popup.call(this)},dotclear.ToolBar.prototype.elements.noembedmedia.fn.markdown=function(){this.elements.noembedmedia.popup.call(this)},dotclear.ToolBar.prototype.elements.noembedmedia.fncall.wiki=function(){const e=this.elements.noembedmedia.gethtml();this.encloseSelection("","",()=>`\n///html\n${e}\n///\n`)},dotclear.ToolBar.prototype.elements.noembedmedia.fncall.xhtml=function(){const e=this.elements.noembedmedia.gethtml();this.encloseSelection("","",()=>e)},dotclear.ToolBar.prototype.elements.noembedmedia.fncall.markdown=function(){const e=this.elements.noembedmedia.gethtml();this.encloseSelection("","",()=>e)}});
